<style>
  /* حاوية التايمر - تم تصغيرها لـ 65px مع إضافة margin للتوسط التام */
  .timer-container {
    position: relative;
    width: 65px;
    height: 65px;
    border-radius: 50%;
    background-color: #f0f4f1; /* نفس لون خلفية الصورة المرسلة */
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.03);
    overflow: hidden;
    margin: 20px auto; /* هذا السطر يضمن توسيط التايمر أفقيًا في الصفحة */
  }

  /* الإطار الأخضر الذي يدور - حركة هادئة وبطيئة */
  .timer-spinner {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: conic-gradient(#005a43 100deg, transparent 100deg);
    border-radius: 50%;
    animation: spin 4s linear infinite; /* 4 ثواني لدوران سلس ومريح */
    z-index: 1;
  }

  /* الدائرة الداخلية - السنتر المطلق */
  .timer-inner {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 59px; /* سمك الإطار 3px دقيق جداً */
    height: 59px;
    background-color: #f0f4f1;
    border-radius: 50%;
    z-index: 2;
    display: grid;
    place-items: center; /* يضع الأرقام في السنتر الميت تماماً */
  }

  /* ضبط النص وحجمه متناسق مع الدائرة الصغيرة */
  #countdown {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    font-size: 14px;
    font-weight: 600;
    color: #1c2d3d;
    line-height: 1;
    margin: 0;
    padding: 0;
  }

  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
</style>

<script>
  // كود الجافاسكريبت لحساب الوقت بدون تغيير
  let timeInSeconds = 4 * 60 + 22; // يبدأ من 04:22 بناءً على الكود الخاص بك
  const timerElement = document.getElementById('countdown');
  const spinnerElement = document.querySelector('.timer-spinner');

  const countdownInterval = setInterval(() => {
    let minutes = Math.floor(timeInSeconds / 60);
    let seconds = timeInSeconds % 60;

    minutes = minutes < 10 ? '0' + minutes : minutes;
    seconds = seconds < 10 ? '0' + seconds : seconds;
    timerElement.textContent = `${minutes}:${seconds}`;

    if (timeInSeconds <= 0) {
      clearInterval(countdownInterval);
      timerElement.textContent = "00:00";
      spinnerElement.style.animation = "none"; 
      spinnerElement.style.background = "transparent"; 
    } else {
      timeInSeconds--;
    }
  }, 1000);
</script>




