<style>
  /* الحاوية الخارجية - حجم أصغر (65px) */
  .timer-container {
    position: relative;
    width: 65px;
    height: 65px;
    border-radius: 50%;
    background-color: #f0f4f1; /* نفس خلفية الصورة */
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.03);
    overflow: hidden;
  }

  /* الإطار الأخضر - دوران بطيء جداً (4 ثواني) */
  .timer-spinner {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: conic-gradient(#005a43 100deg, transparent 100deg);
    border-radius: 50%;
    animation: spin 4s linear infinite;
    z-index: 1;
  }

  /* الدائرة الداخلية - سنتر مطلق ومضمون */
  .timer-inner {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 59px; /* ترك مساحة للإطار بدقة */
    height: 59px;
    background-color: #f0f4f1;
    border-radius: 50%;
    z-index: 2;
    display: grid;
    place-items: center; /* يضع النص في الوسط الميت */
  }

  /* ضبط الخط وحجمه ليناسب الحجم الجديد */
  #countdown {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    font-size: 14px;
    font-weight: 600;
    color: #1c2d3d;
    line-height: 1;
    margin: 0;
    padding: 0;
  }

  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
</style>

<script>
// تحديد عدد الدقائق المطلوبة (4 دقائق)
let startingMinutes = 4;
let time = startingMinutes * 60; // تحويل الدقائق إلى ثوانٍ

const countdownElement = document.getElementById('countdown');

// تشغيل الدالة فوراً مرة واحدة ليظهر الوقت المحدث مباشرة بدون تأخير ثانية
updateCountdown();

// تحديث التايمر كل ثانية واحدة
const timerInterval = setInterval(updateCountdown, 1000);

function updateCountdown() {
  // حساب الدقائق والثواني المتبقية
  let minutes = Math.floor(time / 60);
  let seconds = time % 60;

  // إضافة صفر على اليسار إذا كانت الأرقام أقل من 10
  minutes = minutes < 10 ? '0' + minutes : minutes;
  seconds = seconds < 10 ? '0' + seconds : seconds;

  // التأكد من أن العنصر موجود في الصفحة قبل التحديث لتجنب الأخطاء
  if (countdownElement) {
    countdownElement.innerHTML = `${minutes}:${seconds}`;
  }

  // إيقاف التايمر عند الوصول للرمز 00:00
  if (time <= 0) {
    clearInterval(timerInterval);
    if (countdownElement) {
      countdownElement.innerHTML = "00:00"; 
    }
  } else {
    time--; // إنقاص ثانية واحدة
  }
}
</script>

